export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const
export const MAX_SEED = 2147483646
export const MAX_MOVES = 999999
export const MAX_ELAPSED_MS = 359999999
export const MISMATCH_MS = 800

export type BoardSize = (typeof BOARD_SIZES)[number]
export type Board = Readonly<{
  code: string
  size: BoardSize
  seed: number
  deck: readonly number[]
}>
export type Selection =
  | Readonly<{ kind: 'closed' }>
  | Readonly<{ kind: 'one'; index: number }>
  | Readonly<{ kind: 'mismatch'; first: number; second: number; remainingMs: number }>
export type GameState = Readonly<{
  board: Board
  matched: readonly number[]
  selection: Selection
  moves: number
  elapsedMs: number
  started: boolean
}>
import { BOARD_SIZES, MAX_SEED, type Board, type BoardSize } from './model.ts'

const MODULUS = 2147483647
const MULTIPLIER = 16807
const RANGE = 2147483646

export function parseBoardCode(code: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code)
  const sizeText = match?.[1]
  const seedText = match?.[2]
  if (sizeText === undefined || seedText === undefined) return null
  const size = Number(sizeText)
  const seed = Number(seedText)
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null
  return Object.freeze({ code, size, seed, deck: Object.freeze(makeDeck(size, seed)) })
}

export function isBoardSize(value: number): value is BoardSize {
  return (BOARD_SIZES as readonly number[]).includes(value)
}

function makeDeck(size: BoardSize, seed: number): number[] {
  const deck: number[] = []
  for (let face = 0; face < (size * size) / 2; face += 1) deck.push(face, face)
  let state = seed
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const possible = index + 1
    const limit = Math.floor(RANGE / possible) * possible
    let x = limit
    while (x >= limit) {
      state = (state * MULTIPLIER) % MODULUS
      x = state - 1
    }
    const swapIndex = x % possible
    const current = deck[index]
    const other = deck[swapIndex]
    if (current === undefined || other === undefined) throw new Error('Invalid deck index')
    deck[index] = other
    deck[swapIndex] = current
  }
  return deck
}
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS, type GameState } from './model.ts'
import { parseBoardCode } from './board.ts'

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode)
  if (board === null) return null
  return Object.freeze({
    board,
    matched: Object.freeze([]),
    selection: Object.freeze({ kind: 'closed' as const }),
    moves: 0,
    elapsedMs: 0,
    started: false,
  })
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isSafeInteger(index) || index < 0 || index >= state.board.deck.length || isWon(state)) return state
  if (state.matched.includes(index)) return state
  const selection = state.selection
  if (selection.kind === 'mismatch') return state
  if (selection.kind === 'closed') {
    return Object.freeze({
      ...state,
      selection: Object.freeze({ kind: 'one' as const, index }),
      started: true,
    })
  }
  if (index === selection.index) return state
  const nextMoves = Math.min(MAX_MOVES, state.moves + 1)
  const firstFace = state.board.deck[selection.index]
  const secondFace = state.board.deck[index]
  if (firstFace === secondFace) {
    return Object.freeze({
      ...state,
      matched: Object.freeze([...state.matched, selection.index, index]),
      selection: Object.freeze({ kind: 'closed' as const }),
      moves: nextMoves,
      started: true,
    })
  }
  return Object.freeze({
    ...state,
    selection: Object.freeze({ kind: 'mismatch' as const, first: selection.index, second: index, remainingMs: MISMATCH_MS }),
    moves: nextMoves,
    started: true,
  })
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isSafeInteger(milliseconds) || milliseconds < 0 || !state.started || isWon(state)) return state
  const elapsedMs = milliseconds >= MAX_ELAPSED_MS - state.elapsedMs
    ? MAX_ELAPSED_MS
    : state.elapsedMs + milliseconds
  const selection = state.selection
  if (selection.kind !== 'mismatch') return Object.freeze({ ...state, elapsedMs })
  if (milliseconds >= selection.remainingMs) {
    return Object.freeze({ ...state, elapsedMs, selection: Object.freeze({ kind: 'closed' as const }) })
  }
  return Object.freeze({
    ...state,
    elapsedMs,
    selection: Object.freeze({ ...selection, remainingMs: selection.remainingMs - milliseconds }),
  })
}
import { createGame, isWon } from './transitions.ts'
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS, type GameState, type Selection } from './model.ts'

const MAX_SNAPSHOT_BYTES = 65536
const SNAPSHOT_KEYS = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started']

export function encodeSnapshot(state: GameState): string {
  return JSON.stringify({
    version: 1,
    boardCode: state.board.code,
    matched: state.matched,
    selection: state.selection,
    moves: state.moves,
    elapsedMs: state.elapsedMs,
    started: state.started,
  })
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > MAX_SNAPSHOT_BYTES) return null
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!isRecord(parsed) || !hasExactKeys(parsed, SNAPSHOT_KEYS)) return null
  if (parsed.version !== 1 || typeof parsed.boardCode !== 'string') return null
  if (!isIntegerIn(parsed.moves, 0, MAX_MOVES) || !isIntegerIn(parsed.elapsedMs, 0, MAX_ELAPSED_MS)) return null
  if (typeof parsed.started !== 'boolean' || !Array.isArray(parsed.matched)) return null
  const game = createGame(parsed.boardCode)
  if (game === null) return null
  const matched: number[] = []
  for (const value of parsed.matched) {
    if (!isIndex(value, game.board.deck.length) || matched.includes(value)) return null
    matched.push(value)
  }
  if (matched.length % 2 !== 0 || !matchedFacePairs(game.board.deck, matched)) return null
  const selection = readSelection(parsed.selection, game.board.deck, matched)
  if (selection === null) return null
  const pairs = matched.length / 2
  if (parsed.moves < pairs || (selection.kind === 'mismatch' && parsed.moves < pairs + 1)) return null
  if (!parsed.started) {
    if (parsed.moves !== 0 || parsed.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== 'closed') return null
  } else if (parsed.moves === 0 && selection.kind !== 'one') {
    return null
  }
  const restored: GameState = Object.freeze({
    board: game.board,
    matched: Object.freeze(matched),
    selection,
    moves: parsed.moves,
    elapsedMs: parsed.elapsedMs,
    started: parsed.started,
  })
  if (isWon(restored) && selection.kind !== 'closed') return null
  return restored
}

function readSelection(value: unknown, deck: readonly number[], matched: readonly number[]): Selection | null {
  if (!isRecord(value) || typeof value.kind !== 'string') return null
  if (value.kind === 'closed') return hasExactKeys(value, ['kind']) ? Object.freeze({ kind: 'closed' }) : null
  if (value.kind === 'one') {
    if (!hasExactKeys(value, ['kind', 'index']) || !isIndex(value.index, deck.length) || matched.includes(value.index)) return null
    return Object.freeze({ kind: 'one', index: value.index })
  }
  if (value.kind === 'mismatch') {
    if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null
    if (!isIndex(value.first, deck.length) || !isIndex(value.second, deck.length) || value.first === value.second) return null
    if (matched.includes(value.first) || matched.includes(value.second)) return null
    if (!isIntegerIn(value.remainingMs, 1, MISMATCH_MS)) return null
    if (deck[value.first] === deck[value.second]) return null
    return Object.freeze({ kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs })
  }
  return null
}

function matchedFacePairs(deck: readonly number[], matched: readonly number[]): boolean {
  const faces = new Set<number>()
  for (const index of matched) {
    const face = deck[index]
    if (face === undefined) return false
    faces.add(face)
  }
  for (const face of faces) {
    let count = 0
    for (const index of matched) if (deck[index] === face) count += 1
    if (count !== 2) return false
  }
  return true
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function hasExactKeys(record: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(record)
  return actual.length === keys.length && keys.every((key) => Object.hasOwn(record, key))
}

function isIndex(value: unknown, length: number): value is number {
  return isIntegerIn(value, 0, length - 1)
}

function isIntegerIn(value: unknown, minimum: number, maximum: number): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= minimum && value <= maximum
}

