    const movement = !event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey
    if (!movement) return
    const row = Math.floor(index / side)
    const column = index % side
    let target = index
    if (event.key === 'ArrowLeft' && column > 0) target -= 1
    else if (event.key === 'ArrowRight' && column < side - 1) target += 1
    else if (event.key === 'ArrowUp' && row > 0) target -= side
    else if (event.key === 'ArrowDown' && row < side - 1) target += side
    else return
    event.preventDefault()
    if (target !== index) focusIndex(target)
  }

