              cardSize={cardSize}
              faceId={faceId}
              index={index}
              key={index}
              matched={matched}
              onClick={() => activate(index)}
              onFocus={() => focusFocusedCard(index)}
              onKeyDown={(event) => { markSuppressedKey(event); moveFocus(event, index) }}
